// ==================== Helpers ====================
function formatDateFa(iso?: string | null) {
  if (!iso) return "—";
  try { return new Intl.DateTimeFormat("fa-IR", { dateStyle: "medium" }).format(new Date(iso)); }
  catch { return "—"; }
}

function formatBytes(mb?: number | null) {
  if (!mb && mb !== 0) return "—";
  if (mb < 1) return `${Math.round(mb * 1024)} کیلوبایت`;
  if (mb < 1024) return `${mb.toFixed(1)} مگابایت`;
  return `${(mb / 1024).toFixed(2)} گیگابایت`;
}

function formatMinSec(totalSeconds: number) {
  const m = Math.floor(totalSeconds / 60);
  const s = Math.floor(totalSeconds % 60);
  return `${m}:${String(s).padStart(2, "0")}`;
}

function parseMinSecToSeconds(text: string): number | null {
  const m = /^(\d{1,3}):([0-5]?\d)$/.exec(text.trim());
  if (!m) return null;
  return Number(m[1]) * 60 + Number(m[2]);
}

function parseDurationToSeconds(duration: string | null): number {
  if (!duration) return 0;
  const parts = duration.split(":").map(Number);
  if (parts.length === 2) return (parts[0] || 0) * 60 + (parts[1] || 0);
  if (parts.length === 3) return (parts[0] || 0) * 3600 + (parts[1] || 0) * 60 + (parts[2] || 0);
  return 0;
}

function formatTotalDuration(seconds: number): string {
  if (seconds === 0) return "—";
  const h = Math.floor(seconds / 3600);
  const m = Math.floor((seconds % 3600) / 60);
  if (h > 0) return `${h} ساعت و ${m} دقیقه`;
  return `${m} دقیقه`;
}

async function uploadWithProgress(
  file: File,
  path: string,
  onProgress: (p: number) => void,
): Promise<{ url: string | null; error: string | null }> {
  const { data: sessionData } = await supabase.auth.getSession();
  const accessToken = sessionData.session?.access_token;
  if (!accessToken) return { url: null, error: "نشست ورود معتبر نیست" };

  return new Promise((resolve) => {
    const url = `${SUPABASE_URL}/storage/v1/object/videos/${encodeURIComponent(path)}`;
    const xhr = new XMLHttpRequest();
    xhr.open("POST", url);
    xhr.setRequestHeader("apikey", SUPABASE_PUBLISHABLE_KEY);
    xhr.setRequestHeader("Authorization", `Bearer ${accessToken}`);
    xhr.setRequestHeader("x-upsert", "false");
    xhr.setRequestHeader("content-type", file.type || "application/octet-stream");
    xhr.upload.onprogress = (event) => {
      if (event.lengthComputable) onProgress(Math.round((event.loaded / event.total) * 100));
    };
    xhr.onload = () => {
      if (xhr.status >= 200 && xhr.status < 300) {
        // در دیتابیس فقط path خصوصی ذخیره می‌شود؛ URL امضاشده هنگام نمایش ساخته می‌شود.
        resolve({ url: path, error: null });
      } else {
        resolve({ url: null, error: `آپلود ناموفق (کد ${xhr.status})` });
      }
    };
    xhr.onerror = () => resolve({ url: null, error: "خطای شبکه هنگام آپلود" });
    xhr.send(file);
  });
}

