// ==================== VideoDetailSheet ====================
function VideoDetailSheet({ video, onClose, className, teacherName, students }: {
  video: Video | null; onClose: () => void; className: string;
  teacherName: string; students: StudentLite[];
}) {
  const [progress, setProgress] = useState<WatchProgress[]>([]);
  const [bookmarks, setBookmarks] = useState<VideoBookmark[]>([]);
  const [loadingDetail, setLoadingDetail] = useState(false);
  const [newBookmarkTime, setNewBookmarkTime] = useState("");
  const [newBookmarkNote, setNewBookmarkNote] = useState("");
  const [savingBookmark, setSavingBookmark] = useState(false);
  const [remindingStudentId, setRemindingStudentId] = useState<string | null>(null);

  useEffect(() => {
    if (!video) return;
    setLoadingDetail(true);
    (async () => {
      const [{ data: p, error: pErr }, { data: b, error: bErr }] = await Promise.all([
        supabase.from("video_watch_progress").select("*").eq("video_id", video.id),
        supabase.from("video_bookmarks").select("*").eq("video_id", video.id).order("timestamp_seconds"),
      ]);
      if (!pErr) {
        setProgress(
          ((p ?? []) as Array<Record<string, any>>).map((row) => ({
            ...row,
            id: String(row.id),
            video_id: String(row.video_id),
            student_id: String(row.student_id),
            watched_seconds: Number(row.watched_seconds ?? 0),
            percent: Number(row.percent ?? 0),
            last_position_seconds: Number(row.last_position_seconds ?? 0),
            duration_seconds: row.duration_seconds == null ? null : Number(row.duration_seconds),
            last_watched_at: String(row.last_watched_at ?? ""),
            completed_at: row.completed_at == null ? null : String(row.completed_at),
          })) as WatchProgress[],
        );
      } else setProgress([]);
      if (!bErr) setBookmarks((b as VideoBookmark[]) ?? []); else setBookmarks([]);
      setLoadingDetail(false);
    })();
  }, [video?.id]);

  if (!video) return null;

  const watchedStudentIds = new Set(progress.map(p => p.student_id));
  const watchedStudents = students.filter(s => watchedStudentIds.has(s.id));
  const notWatchedStudents = students.filter(s => !watchedStudentIds.has(s.id));
  const chartData = [...progress].sort((a, b) => a.last_watched_at.localeCompare(b.last_watched_at))
    .map((p, idx) => ({ name: formatDateFa(p.last_watched_at), بازدید: idx + 1 }));

  const addBookmark = async () => {
    const seconds = parseMinSecToSeconds(newBookmarkTime);
    if (seconds === null) { toast.error("زمان را به‌صورت دقیقه:ثانیه وارد کنید"); return; }
    if (!newBookmarkNote.trim()) { toast.error("یادداشت را وارد کنید"); return; }
    setSavingBookmark(true);
    const { data, error } = await supabase.from("video_bookmarks")
      .insert([{ video_id: video.id, timestamp_seconds: seconds, note: newBookmarkNote.trim() }])
      .select("*").single();
    setSavingBookmark(false);
    if (error) toast.error("خطا در ثبت نشانه");
    else {
      setBookmarks(prev => [...prev, data as VideoBookmark].sort((a, b) => a.timestamp_seconds - b.timestamp_seconds));
      setNewBookmarkTime(""); setNewBookmarkNote(""); toast.success("نشانه ثبت شد");
    }
  };

  const sendWatchReminder = async (student: StudentLite) => {
    setRemindingStudentId(student.id);
    try {
      const result = await sendSecureMessage({
        targetType: "student",
        targetId: student.id,
        subject: `یادآوری مشاهده ویدیو: ${video.title}`,
        content: `لطفاً ویدیوی آموزشی «${video.title}» را در اولین فرصت مشاهده کنید.`,
        priority: "normal",
        topic: "educational",
      });
      toast.success(
        result.recipientCount > 0
          ? `یادآوری امن برای «${student.name}» ارسال شد`
          : "حساب فعال گیرنده یافت نشد",
      );
    } catch (error) {
      toast.error(error instanceof Error ? error.message : "ارسال یادآوری ناموفق بود");
    } finally {
      setRemindingStudentId(null);
    }
  };

  return (
    <Sheet open={!!video} onOpenChange={o => !o && onClose()}>
      <SheetContent side="left" className="w-full sm:max-w-2xl overflow-y-auto" dir="rtl">
        <SheetHeader>
          <SheetTitle className="text-right font-black text-[#2d2620]">{video.title}</SheetTitle>
        </SheetHeader>
        <div className="space-y-5 mt-4">
          <div className="overflow-hidden rounded-2xl bg-black shadow-md">
            <ResolvedVideoPreview
              videoId={video.id}
              originalUrl={video.video_url}
              resolvedUrl={video.resolved_video_url || ""}
              sourceType={video.source_type}
              posterUrl={video.resolved_thumbnail_url}
              title={video.title}
            />
          </div>
          <Card className="quran-soft-clay-card shadow-sm p-4 space-y-2.5">
            <div className="flex items-center justify-between text-sm">
              <span className="text-muted-foreground">استاد / کلاس</span>
              <span className="font-bold text-[#2d2620]">{className} • {teacherName}</span>
            </div>
            <div className="flex items-center justify-between text-sm">
              <span className="text-muted-foreground">تاریخ آپلود</span>
              <span className="font-bold text-[#2d2620]">{formatDateFa(video.created_at)}</span>
            </div>
            <div className="flex items-center justify-between text-sm">
              <span className="text-muted-foreground">حجم فایل</span>
              <span className="font-bold text-[#2d2620]">{formatBytes(video.file_size_mb)}</span>
            </div>
            <div className="flex items-center justify-between text-sm">
              <span className="text-muted-foreground">وضعیت</span>
              <Badge variant={video.locked ? "destructive" : "outline"} className="gap-1 border-0 rounded-md">
                {video.locked ? <Lock className="h-3 w-3" /> : <Unlock className="h-3 w-3" />}
                {video.locked ? "قفل شده" : "آزاد"}
              </Badge>
            </div>
            {video.description && <p className="text-sm pt-2 text-[#2d2620] font-sans border-t border-border/40 mt-2">{video.description}</p>}
            {video.tags && video.tags.length > 0 && (
              <div className="flex flex-wrap gap-1 pt-2 border-t border-border/40 mt-2">
                {video.tags.map(t => <Badge key={t} variant="outline" className="text-[10px] border-[#5d6d45]/30 text-[#4a5839] bg-[#5d6d45]/5">{t}</Badge>)}
              </div>
            )}
            {(video.related_surah || video.related_ayah) && (
              <div className="flex items-center gap-2 pt-2.5 text-sm text-[#4a5839] font-black border-t border-border/40 mt-2">
                <BookOpen className="h-4 w-4" />
                <span>{video.related_surah} {video.related_ayah && `— ${video.related_ayah}`}</span>
              </div>
            )}
          </Card>
          <Card className="quran-soft-clay-card shadow-sm p-4">
            <h4 className="text-sm font-semibold mb-3 flex items-center gap-1.5 text-[#2d2620] font-black">
              <BarChart3 className="h-4 w-4 text-[#4a5839]" />بازدید در طول زمان
            </h4>
            {chartData.length === 0 ? (
              <p className="text-xs text-muted-foreground py-6 text-center">هنوز آماری ثبت نشده.</p>
            ) : (
              <div className="h-48">
                <ResponsiveContainer width="100%" height="100%">
                  <AreaChart data={chartData}>
                    <defs>
                      <linearGradient id="viewsGradient" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="5%" stopColor="#4a5839" stopOpacity={0.4} />
                        <stop offset="95%" stopColor="#4a5839" stopOpacity={0} />
                      </linearGradient>
                    </defs>
                    <CartesianGrid strokeDasharray="3 3" opacity={0.2} />
                    <XAxis dataKey="name" fontSize={10} />
                    <YAxis fontSize={10} allowDecimals={false} />
                    <RTooltip />
                    <Area type="monotone" dataKey="بازدید" stroke="#4a5839" fill="url(#viewsGradient)" />
                  </AreaChart>
                </ResponsiveContainer>
              </div>
            )}
          </Card>
          <Card className="quran-soft-clay-card shadow-sm p-4">
            <h4 className="text-sm font-semibold mb-3 flex items-center gap-1.5 text-[#2d2620] font-black">
              <CheckCircle2 className="h-4 w-4 text-[#4a5839]" />مشاهده‌کرده‌اند ({toFa(watchedStudents.length)})
            </h4>
            {loadingDetail ? <Loader2 className="h-4 w-4 animate-spin mx-auto text-primary" /> :
              watchedStudents.length === 0 ? <p className="text-xs text-muted-foreground text-center py-3">کسی ندیده است.</p> : (
                <div className="space-y-2.5">
                  {watchedStudents.map(s => {
                    const p = progress.find(pr => pr.student_id === s.id);
                    return (
                      <div key={s.id} className="rounded-xl border bg-white/60 p-3 text-sm">
                        <div className="flex flex-wrap items-center justify-between gap-2">
                          <span className="truncate font-semibold text-[#2d2620]">{s.name}</span>
                          {p?.completed_at && (
                            <Badge className="border-0 bg-emerald-100 text-emerald-800">تکمیل‌شده</Badge>
                          )}
                        </div>
                        <div className="mt-2 grid gap-2 text-[10px] text-muted-foreground sm:grid-cols-3">
                          <span>آخرین مشاهده: {p?.last_watched_at ? formatDateFa(p.last_watched_at) : "—"}</span>
                          <span>زمان فعال: {toFa(formatMinSec(p?.watched_seconds ?? 0))}</span>
                          <span>آخرین نقطه: {toFa(formatMinSec(p?.last_position_seconds ?? 0))}</span>
                        </div>
                        <div className="mt-2 flex items-center gap-2">
                          <Progress value={p?.percent ?? 0} className="flex-1" />
                          <span className="w-10 text-left text-[11px] font-bold">
                            {toFa(Math.round(p?.percent ?? 0))}٪
                          </span>
                        </div>
                      </div>
                    );
                  })}
                </div>
              )}
          </Card>
          <Card className="quran-soft-clay-card shadow-sm p-4">
            <h4 className="text-sm font-semibold mb-3 flex items-center gap-1.5 text-[#2d2620] font-black">
              <BellRing className="h-4 w-4 text-destructive" />هنوز ندیده‌اند ({toFa(notWatchedStudents.length)})
            </h4>
            {notWatchedStudents.length === 0
              ? <p className="text-xs text-muted-foreground text-center py-3">همه دیده‌اند.</p>
              : (
                <div className="space-y-2.5">
                  {notWatchedStudents.map(s => (
                    <div key={s.id} className="flex items-center justify-between gap-2 text-sm">
                      <span className="truncate font-semibold text-[#2d2620]">{s.name}</span>
                      <Button
                        size="sm"
                        variant="outline"
                        className="gap-1.5 shrink-0 rounded-lg text-xs font-bold"
                        disabled={remindingStudentId === s.id}
                        onClick={() => void sendWatchReminder(s)}
                      >
                        {remindingStudentId === s.id ? (
                          <Loader2 className="h-3.5 w-3.5 animate-spin" />
                        ) : (
                          <BellRing className="h-3.5 w-3.5 text-destructive" />
                        )}
                        یادآوری
                      </Button>
                    </div>
                  ))}
                </div>
              )}
          </Card>
          <Card className="quran-soft-clay-card shadow-sm p-4">
            <h4 className="text-sm font-semibold mb-3 flex items-center gap-1.5 text-[#2d2620] font-black">
              <Bookmark className="h-4 w-4 text-gold" />نشانه‌های مهم
            </h4>
            {bookmarks.length > 0 && (
              <div className="space-y-1.5 mb-3">
                {bookmarks.map(b => (
                  <div key={b.id} className="flex items-center gap-2 text-sm rounded-xl bg-[#efebd9]/50 px-3 py-2 font-bold text-[#2d2620]">
                    <Badge variant="outline" className="text-[10px] shrink-0 border-[#5d6d45]/30 text-[#4a5839] bg-[#5d6d45]/5">{toFa(formatMinSec(b.timestamp_seconds))}</Badge>
                    <span className="truncate">{b.note}</span>
                  </div>
                ))}
              </div>
            )}
            <div className="flex gap-2">
              <Input placeholder="5:20" value={newBookmarkTime} onChange={e => setNewBookmarkTime(e.target.value)} className="w-20" dir="ltr" />
              <Input placeholder="یادداشت..." value={newBookmarkNote} onChange={e => setNewBookmarkNote(e.target.value)} className="flex-1" />
              <Button size="sm" onClick={addBookmark} disabled={savingBookmark}
                className="shrink-0 gradient-primary text-primary-foreground rounded-lg h-9">
                {savingBookmark ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Plus className="h-3.5 w-3.5" />}
              </Button>
            </div>
          </Card>
        </div>
      </SheetContent>
    </Sheet>
  );
}

